const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),assert=require('node:assert/strict');
const project=path.resolve(__dirname,'../../..');
function createHarness(){
 const nodes={},events={},netListeners={},sent=[],scheduled=[],counts={created:0,deleted:0,text:0,style:0,tree:0,grid:0};let serial=0,steam='76561198000000000',tools=false,profile={vip_badge:0},history={history:[]};
 class Panel{
  constructor(type,parent,id=''){this.id=id;this.paneltype=type;this.parent=parent;this.children=[];this.classes=new Set();this.events={};this.visible=true;this.enabled=true;this.actualuiscale_x=this.actualuiscale_y=1;this.style=new Proxy({},{set:(o,k,v)=>{counts.style++;o[k]=v;return true;}});counts.created++;if(parent)parent.children.push(this);if(id)nodes[id]=this;}
  check(){assert(!this.deleted,'native methods cannot access deleted panels');}IsValid(){return !this.deleted;}AddClass(c){this.check();c.split(/\s+/).forEach(x=>this.classes.add(x));}RemoveClass(c){this.check();this.classes.delete(c);}ToggleClass(c){this.check();this.classes.has(c)?this.classes.delete(c):this.classes.add(c);}BHasClass(c){this.check();return this.classes.has(c);}SetHasClass(c,v){v?this.AddClass(c):this.RemoveClass(c);}
  Children(){this.check();counts.tree++;return this.children;}GetChildCount(){this.check();return this.children.length;}GetChild(index){this.check();return this.children[index];}GetParent(){this.check();return this.parent;}SetParent(p){this.check();if(this.parent)this.parent.children=this.parent.children.filter(c=>c!==this);this.parent=p;p.children.push(this);}FindChildTraverse(id){this.check();counts.tree++;if(this.id===id)return this;for(const c of this.children){const n=c.FindChildTraverse(id);if(n)return n;}return null;}
  SetPanelEvent(k,v){this.check();this.events[k]=v;}SetImage(uri){this.check();this.image=uri;}SetScaling(mode){this.check();this.scaling=mode;}SetFocus(){}ScrollToTop(){}MoveChildBefore(c,b){this.children=this.children.filter(x=>x!==c);this.children.splice(Math.max(0,this.children.indexOf(b)),0,c);}DeleteAsync(){this.check();this.children.slice().forEach(c=>c.DeleteAsync());this.deleted=true;counts.deleted++;if(nodes[this.id]===this)delete nodes[this.id];if(this.parent)this.parent.children=this.parent.children.filter(c=>c!==this);}RemoveAndDeleteChildren(){this.check();if(this.id==='VIPGrid')counts.grid++;this.children.slice().forEach(c=>c.DeleteAsync());}
  set text(v){this.check();this._text=String(v);counts.text++;}get text(){this.check();return this._text||'';}get actuallayoutwidth(){return Number.parseFloat(this.style.width)||120;}get actuallayoutheight(){if(this.style.height==='fit-children'&&this.paneltype==='Label')return Math.ceil(Math.max(1,this.text.length/(276/9)))*24;return Number.parseFloat(this.style.height)||28;}GetPositionWithinWindow(){this.check();let x=0,y=0,n=this;while(n){const p=String(n.style.position||'0px 0px').split(' ');x+=parseFloat(p[0])||0;y+=parseFloat(p[1])||0;n=n.parent;}return {x,y};}
 }
 const root=new Panel('Panel',null,'Root');root.style.width='1920px';root.style.height='1080px';
 const xml=fs.readFileSync(path.join(project,'panorama/src/layout/custom_game/archive.xml'),'utf8'),tokens=xml.match(/<\/?(?:Panel|Button|RadioButton|Label|Image)\b[^>]*>/g),stack=[root];
 for(const t of tokens){if(t.startsWith('</')){stack.pop();continue;}const type=t.match(/^<(\w+)/)[1],id=(t.match(/\bid="([^"]*)"/)||[])[1]||'',p=new Panel(type,stack.at(-1),id);const cls=(t.match(/\bclass="([^"]*)"/)||[])[1];if(cls)p.AddClass(cls);const text=(t.match(/\btext="([^"]*)"/)||[])[1];if(text!==undefined)p.text=text;if(!t.endsWith('/>'))stack.push(p);}
 function schedule(delay,fn,guard){const item={id:++serial,delay,fn,guard,cancelled:false};scheduled.push(item);return item.id;}
 const cfg={SurvivalDevelopmentPayments:true,HandoffGeneration:3,SurvivalCommerceWallet:{GetCatalog:()=>({balances:{u_coin:23,shop_points:34,shop_gold:56}})}};
 const state={Set(p,v){if(v.enabled!==undefined)p.enabled=v.enabled;if(v.busy!==undefined)p.busy=v.busy;},Bind(p,fn){p.events.onactivate=()=>{if(p.enabled!==false)fn();};}};
 cfg.SurvivalUI={State:state,Fit:()=>1,ActionButton:{Adopt(p,props){state.Bind(p,props.action);return p;}},Lifecycle(){let active=true,epoch=0;const subscriptions=[];return {Subscribe(name,fn){const id=++serial;events[name]={id,fn:(...a)=>{if(active)fn(...a);}};subscriptions.push([name,id]);return id;},Later(delay,fn){const value=epoch;return schedule(delay,()=>{if(active&&epoch===value)fn();});},Cancel(){epoch++;},Dispose(){active=false;epoch++;for(const [name,id]of subscriptions)if(events[name]?.id===id)delete events[name];}};},ModalShell:{Adopt(props){let opened=false;return {Open(){opened=true;props.panel.visible=true;props.panel.RemoveClass('UIClosed');if(props.scrim)props.scrim.visible=true;},Close(){opened=false;if(props.panel.IsValid()){props.panel.visible=false;props.panel.AddClass('UIClosed');}if(props.scrim&&props.scrim.IsValid())props.scrim.visible=false;},IsOpen(){return opened;},RequestClose:props.onClose,Dispose(){this.Close();}};}}};
 cfg.RemainingHandoff={DailyImage(parent,id,cls){const p=new Panel('Image',parent);p.SetImage('fixture://'+id);p.AddClass(cls);return p;},DailyResourceInfo:()=>({runtime:'fixture.png'}),DailyPass(){},Action(){}};
 const $={GetContextPanel:()=>root,CreatePanel:(type,parent,id)=>new Panel(type,parent,id),Schedule:schedule,CancelScheduled(id){const item=scheduled.find(x=>x.id===id);if(item)item.cancelled=true;},RegisterEventHandler(name,panel,fn){(panel.handlers||(panel.handlers={}))[name]=fn;},Msg(){},DispatchEvent(){}};
 const env={GameUI:{CustomUIConfig:()=>cfg},Game:{GetLocalPlayerID:()=>0,IsInToolsMode:()=>tools,GetPlayerInfo:()=>({player_steamid:steam}),AddCommand(){}},$,
  CustomNetTables:{GetTableValue(name){return name==='survival_player_public_profiles'?profile:name==='survival_rogue_reward'?history:name==='survival_ui_state'?{resources:{gold:1,wood:2}}:null;},SubscribeNetTableListener(name,fn){const id=++serial;(netListeners[name]||(netListeners[name]=[])).push({id,fn});return id;},UnsubscribeNetTableListener(id){for(const name of Object.keys(netListeners))netListeners[name]=netListeners[name].filter(x=>x.id!==id);}},
  GameEvents:{Subscribe(name,fn){const id=++serial;events[name]={id,fn};return id;},Unsubscribe(id){for(const name of Object.keys(events))if(events[name].id===id)delete events[name];},SendCustomGameEventToServer(name,payload){sent.push({name,payload});}}};
 const context=vm.createContext(env),load=name=>vm.runInContext(fs.readFileSync(path.join(project,'panorama/src/scripts/custom_game',name),'utf8'),context,{filename:name});
 load('archive_v10_data.js');load('common/tooltip_dismiss.js');load('common/menu_v10.js');
 return {cfg,nodes,root,sent,counts,scheduled,load,setCursor(x,y){env.GameUI.GetCursorPosition=()=>[x,y];},emit(name,value){assert(events[name],name+' listener is registered');events[name].fn(value);},net(name,key,value){for(const item of (netListeners[name]||[]).slice())item.fn(name,key,value);},setProfile(value){profile=value;},setHistory(value){history=value;},setIdentity(value,mode){steam=value;tools=mode;},flushFinite(){const work=scheduled.splice(0).filter(x=>x.delay<=.8&&!x.cancelled);work.forEach(x=>x.fn());},click(p){if(p.enabled!==false)p.events.onactivate();},view(id){return cfg.SurvivalMenuV10.Entries().find(v=>v.panel.id===id);},assertCleanDispose(api){const timers=scheduled.slice();root.DeleteAsync();assert.doesNotThrow(()=>{timers.filter(x=>!x.cancelled).forEach(x=>x.fn());api.Close();api.Dispose();api.Dispose();});}};
}
module.exports={createHarness};
